onReady() {
  var session = dataInterface.getSessionSummary();
  if (session) {
    this.hasLastSession = true;
    this.lastDuration = (session.durationSec / 60).toFixed(1);
    this.lastPunches = String(session.totalPunches);
    var avg = 0;
    if (session.roundBreakdown && session.roundBreakdown.length > 0) {
      var sum = 0;
      for (var i = 0; i < session.roundBreakdown.length; i++) {
